from pathlib import Path
import json, uuid, datetime
R=Path('/tmp/pkg')
# version
p=R/'manifest.json'; m=json.loads(p.read_text()); m['version']='2.2.6'; p.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
p=R/'build-info.json'; b=json.loads(p.read_text()); b['version']='2.2.6'; b['buildId']=str(uuid.uuid4()); b['createdAt']=datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace('+00:00','Z');
if 'CHANGELOG-v2.2.6.md' not in b['managedFiles']: b['managedFiles'].append('CHANGELOG-v2.2.6.md')
p.write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n')
(R/'CHANGELOG-v2.2.6.md').write_text('''# Entry Live Studio v2.2.6\n\n- 방 추천을 공통 방 이력이 있는 사용자로 제한하지 않고 정확한 사용자 이름 기반 실시간 채널로 전송합니다.\n- 같은 이름으로 현재 접속 중인 사용자는 자신의 이름 전용 채널에서 추천을 받으며, 이미 해당 방에 참가 중이면 추천 알림을 무시합니다.\n- 대표가 보내는 room-meta에 완전한 멤버십 표시를 추가해 오프라인 중 놓친 실제 방 나가기까지 재접속 후 정리합니다.\n- v2.2.5의 오프라인/퇴장 구분, 알림 UI, 스크롤 복원과 기존 기능을 유지합니다.\n''')

